def  open_tsp(dist: list[list[int]]) -> int:
    n = len(dist)
    # dp[mask][i] = min cost to visit nodes in mask ending at i
    dp = [[float('inf')] * n for _ in range(1 << n)]
    dp[0][0] = 0
    for mask in range(1 << n):
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            if dp[mask][i] == float('inf'):
                continue
            for j in range(n):
                if mask & (1 << j):
                    continue
                dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + dist[i][j])
    ans = min(dp[(1 << n) - 1][i] for i in range(n))
    return ans

