def  longest_valid_parentheses(s: str) -> int:
    stack = []
    max_len = 0
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
                max_len = max(max_len, i - stack[-1] if stack else i)
    return max_len

